describe('Responsive Font Size Test', () => {
    beforeEach(() => {
        cy.visit('https://example.com'); // Replace with the actual URL of the application
        cy.viewport('iphone-6'); // Simulate a small screen
    });

    it('should display readable font size on small screens', () => {
        cy.get('body').should('have.css', 'font-size').and('match', /16px/); // Adjust expected font size as necessary
    });

    it('should not require zooming to read the text', () => {
        cy.get('body').then(($body) => {
            const fontSize = parseFloat($body.css('font-size'));
            expect(fontSize).to.be.greaterThan(12); // Ensure font size is greater than a minimum readable size
        });
    });
});
